250	    const requestId = makeRequestId();
251	    const submittedAt = Date.now();
252	    const mode: OracleCommandMode = options.useCouncil ? 'council' : 'direct';
253	    const controller = new AbortController();
254	    const upstreamSignal = options.signal;
255	    const relayAbort = () => controller.abort();
256	
257	    if (upstreamSignal) {
258	        if (upstreamSignal.aborted) {
259	            controller.abort();
260	        } else {
261	            upstreamSignal.addEventListener('abort', relayAbort, { once: true });
262	        }
263	    }
264	
265	    activeController = controller;
266	
267	    setState({
268	        requestId,
269	        source: options.source || 'typed',
270	        mode,
271	        phase: 'submitted',
272	        staleLevel: null,
273	        command,
274	        response: null,
275	        error: null,
276	        submittedAt,
277	        settledAt: null,
278	        elapsedMs: 0
279	    });
280	
281	    startElapsedClock(requestId);
282	    schedulePhaseTimers(requestId);
283	
284	    try {
285	        const response = await apiFetchWithTimeout(ORACLE_COMMAND_ENDPOINT, hardTimeoutForMode(mode), {
286	            method: 'POST',
287	            headers: { 'Content-Type': 'application/json' },
288	            body: JSON.stringify({
289	                command,
290	                useCouncil: mode === 'council',
291	                modelId: mode === 'direct' ? options.modelId || undefined : undefined
292	            }),
293	            signal: controller.signal
294	        });
295	
296	        const payload = await response.json().catch(() => ({} as OracleCommandResponse));
297	        if (!response.ok) {
298	            const message = String(
299	                (payload as Record<string, unknown>)?.message
300	                || (payload as Record<string, unknown>)?.error
301	                || `HTTP_${response.status}`
302	            );
303	            throw new Error(message);
304	        }
305	
306	        settleRequest(requestId, 'completed', {
307	            response: payload,
308	            error: null
309	        });
310	        return payload;
311	    } catch (error) {
312	        if (state.requestId === requestId) {
313	            settleRequest(requestId, 'failed', {
314	                response: null,
315	                error: normalizeError(error)
316	            });
317	        }
318	        throw error;
319	    } finally {
320	        if (upstreamSignal) {
321	            upstreamSignal.removeEventListener('abort', relayAbort);
322	        }
323	        if (activeController === controller) {
324	            activeController = null;
325	        }
326	    }
